                    <kbd className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-black text-slate-400 uppercase tracking-tighter">Ctrl + K for Commands</kbd>
                  </div>
                  <div className="flex items-end justify-between gap-4 h-48 mt-10">
                     {[40, 70, 55, 90, 80, 60, 30, 85, 45, 50, 65, 95].map((h, i) => (
                       <div key={i} className="flex-1 bg-slate-50 rounded-xl relative group overflow-hidden h-full flex flex-col justify-end">
                          <div className="w-full bg-indigo-600/10 rounded-xl transition-all duration-1000 group-hover:bg-indigo-600" style={{ height: `${h}%` }} />
                       </div>
                     ))}
                  </div>
               </div>

               <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden flex flex-col">
                  <div className="absolute top-0 right-0 h-40 w-40 bg-indigo-500/20 blur-3xl rounded-full -mr-10 -mt-10" />
                  <h3 className="text-xl font-black uppercase tracking-tight relative z-10 mb-8">Quick Actions</h3>
                  <div className="space-y-4 relative z-10 flex-1">
                     <button onClick={() => setIsPaletteOpen(true)} className="w-full flex items-center justify-between p-4 bg-white/5 border border-white/10 rounded-2xl hover:bg-indigo-600 transition-all">
                        <span className="text-[10px] font-black uppercase tracking-widest">Global Launcher</span>
                        <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                     </button>
                     <button onClick={() => handleViewChange('admin-add-invoice')} className="w-full flex items-center justify-between p-4 bg-white/5 border border-white/10 rounded-2xl hover:bg-indigo-600 transition-all">
                        <span className="text-[10px] font-black uppercase tracking-widest">Generate Bill</span>
                        <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                     </button>
