import React, { useState, useEffect } from 'react';
import { Client, ConstitutionType, GstStatus, GstRegType, GstFilingFreq, ClientStatus, JurisdictionType } from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'basic' | 'filing' | 'admin'>('basic');

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '', tradeName: '', email: '', mobile: '', status: 'Active Filing',
    gstProfile: {
      gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
      regDate: '', regType: 'Regular', filingFreq: 'Monthly',
      constitution: 'Proprietorship', stakeholders: [],
      accountantName: '', accountantMobile: '', address: '',
      jurisdictionType: 'State', sector: '', range: ''
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (initialData) setFormData(initialData);
    else setFormData({
      legalName: '', tradeName: '', email: '', mobile: '', status: 'Active Filing',
      gstProfile: {
        gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
        regDate: '', regType: 'Regular', filingFreq: 'Monthly',
        constitution: 'Proprietorship', stakeholders: [],
        accountantName: '', accountantMobile: '', address: '',
        jurisdictionType: 'State', sector: '', range: ''
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
    setActiveTab('basic');
  }, [initialData, isOpen]);

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().trim().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';

    // Power-User Logic: Auto-derive PAN from GSTIN (Positions 3-12)
    if (gstin.length >= 12) {
      pan = gstin.substring(2, 12);
    }

    setFormData(prev => ({
      ...prev,
      gstProfile: { ...prev.gstProfile!, gstin, pan }
    }));

    // Reset error if user is typing a potentially valid ID
    if (error && gstin.length < 15) setError(null);
  };

  const handleReturnLogic = (type: GstRegType) => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        regType: type,
        filingFreq: type === 'Composition' ? 'Quarterly' : prev.gstProfile?.filingFreq || 'Monthly'
      }
    }));
  };

  const handleSave = async () => {
    setError(null);
    // Structural Validation
    if (!formData.legalName) return setError("Entity Legal Name is mandatory.");
    if (formData.gstProfile?.gstin?.length !== 15) return setError("GSTIN must be exactly 15 characters.");

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Vault sync failed.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95">
        <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50 shrink-0 rounded-t-[2rem]">
          <div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">GST Master Record</h2>
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mt-1">Practice Management Hub</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-lg transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
          </button>
        </div>

        <div className="flex border-b border-slate-100 bg-white shrink-0 overflow-x-auto no-scrollbar">
           {[
             { id: 'basic', label: '1. Basic Identity' },
             { id: 'filing', label: '2. Filing Config' },
             { id: 'admin', label: '3. Administrative' }
           ].map((t) => (
             <button key={t.id} onClick={() => setActiveTab(t.id as any)} 
               className={`flex-1 py-4 px-6 text-[10px] font-black uppercase tracking-widest transition-all border-b-2 whitespace-nowrap ${activeTab === t.id ? 'border-indigo-600 text-indigo-600 bg-indigo-50/30' : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>
               {t.label}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
          {error && <div className="p-4 bg-red-50 text-red-600 rounded-xl font-black border border-red-100 text-[10px] uppercase tracking-widest animate-in shake duration-300">{error}</div>}

          {activeTab === 'basic' && (
            <div className="space-y-8 animate-in fade-in duration-300">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="md:col-span-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">GSTIN Identifier</label>
                    <div className="relative group">
                       <input 
                         autoFocus
                         className="w-full bg-slate-50 border border-slate-200 p-4 rounded-xl font-black uppercase font-mono tracking-[0.2em] outline-none focus:ring-4 focus:ring-indigo-100 transition-all text-lg text-indigo-600" 
                         placeholder="22AAAAA0000A1Z5" 
                         value={formData.gstProfile?.gstin} 
                         onChange={e => handleGstinChange(e.target.value)} 
                       />
                       {formData.gstProfile?.gstin?.length === 15 && (
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 h-6 w-6 rounded-full bg-emerald-500 text-white flex items-center justify-center shadow-lg animate-in zoom-in">
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                         </div>
                       )}
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Legal Name (As per PAN)</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold uppercase outline-none focus:ring-4 focus:ring-indigo-50" value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} placeholder="Full Entity Name" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Derived PAN</label>
                    <input readOnly className="w-full bg-slate-100 border border-slate-200 p-3.5 rounded-xl font-black uppercase font-mono tracking-widest text-slate-400 cursor-not-allowed" value={formData.gstProfile?.pan} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Trade/Business Name</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold uppercase outline-none focus:ring-4 focus:ring-indigo-50" value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} placeholder="Brand Name" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Mobile No</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none" value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value})} placeholder="Primary Contact" />
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'filing' && (
            <div className="space-y-8 animate-in fade-in duration-300">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Taxpayer Category</label>
                    <select className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none" value={formData.gstProfile?.regType} onChange={e => handleReturnLogic(e.target.value as GstRegType)}>
                       <option value="Regular">Regular Taxpayer</option>
                       <option value="Composition">Composition Dealer</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Filing Frequency</label>
                    <select disabled={formData.gstProfile?.regType === 'Composition'} className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none disabled:opacity-50" value={formData.gstProfile?.filingFreq} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, filingFreq: e.target.value as GstFilingFreq}})}>
                       <option value="Monthly">Monthly</option>
                       <option value="Quarterly">Quarterly (QRMP)</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Vault Status</label>
                    <select className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as ClientStatus})}>
                       <option value="Active Filing">Active Filing</option>
                       <option value="Inactive">Inactive</option>
                       <option value="Case-by-Case">Litigation Only</option>
                    </select>
                  </div>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Portal Password</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none" value={formData.gstProfile?.password} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, password: e.target.value}})} placeholder="Secure Password" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Effective Reg. Date</label>
                    <input type="date" className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none uppercase" value={formData.gstProfile?.regDate} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, regDate: e.target.value}})} />
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'admin' && (
            <div className="space-y-8 animate-in fade-in duration-300">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Jurisdiction</label>
                    <select className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none" value={formData.gstProfile?.jurisdictionType} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, jurisdictionType: e.target.value as JurisdictionType}})}>
                       <option value="State">State Jurisdiction</option>
                       <option value="Center">Central Jurisdiction</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Sector/Circle</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none uppercase" value={formData.gstProfile?.sector} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, sector: e.target.value}})} placeholder="E.G. CIRCLE 4" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Range/Ward</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold outline-none uppercase" value={formData.gstProfile?.range} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, range: e.target.value}})} placeholder="E.G. WARD 12" />
                  </div>
               </div>
               <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block ml-1">Internal Firm Remarks</label>
                  <textarea className="w-full bg-slate-50 border border-slate-200 p-4 rounded-xl font-medium text-slate-600 outline-none h-24 focus:ring-4 focus:ring-indigo-100" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Staff instructions, pending issues, or history..." />
               </div>
            </div>
          )}
        </div>

        <div className="p-8 border-t border-slate-100 bg-slate-50 flex gap-3 shrink-0 rounded-b-[2rem]">
          <button onClick={onClose} className="flex-1 py-4 rounded-xl text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 hover:bg-white transition-all">Discard Changes</button>
          <button onClick={handleSave} disabled={isSaving} className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98]">
            {isSaving ? 'Encrypting...' : 'Commit Master Record'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default GSTClientFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types.ts';
import { api } from '../../services/api.ts';
import GSTClientFormModal from '../Clientform/GSTClientFormModal.tsx';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  onDataChange?: () => void;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const fetch = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    } catch (err) { console.error("Fetch failed", err); } finally { setIsLoading(false); }
  };

  useEffect(() => { fetch(); }, []);

  const handleDataChange = () => {
    fetch();
    if (onDataChange) onDataChange();
  };

  const handleDelete = async (client: Client) => {
    // Power-User UX: Proactive Error Prevention / Safety Guardrails
    try {
      const summary = await api.getDashboardSummary();
      const activeLitigation = summary.litigation.filter(l => l.clientId === client.id && l.status === 'Pending');
      const pendingInvoices = summary.invoices.filter(i => i.clientId === client.id && i.status !== 'Paid');

      if (activeLitigation.length > 0 || pendingInvoices.length > 0) {
        let msg = `SAFE-DELETE BLOCKED: ${client.legalName} has `;
        if (activeLitigation.length > 0) msg += `${activeLitigation.length} active litigation cases. `;
        if (pendingInvoices.length > 0) msg += `${pendingInvoices.length} unpaid invoices. `;
        msg += "\n\nPlease settle all matters before removing this master record.";
        alert(msg);
        return;
      }

      if (confirm(`CAUTION: Permanently delete ${client.legalName}? This action cannot be undone.`)) {
        await api.deleteClient(client.id);
        handleDataChange();
      }
    } catch (err) { alert("Security check failed. Delete aborted."); }
  };

  const filteredClients = useMemo(() => {
    const s = externalSearch.toLowerCase();
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );
  }, [clients, externalSearch]);

  const copyToClipboard = (text: string) => navigator.clipboard.writeText(text);

  if (isLoading) return (
    <div className="flex-1 flex flex-col items-center justify-center p-20 space-y-4">
       <div className="h-10 w-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin" />
       <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Accessing Secured Vault</p>
    </div>
  );

  return (
    <div className="flex-1 flex flex-col min-h-0">
      <div className="overflow-x-auto no-scrollbar flex-1">
        <table className="w-full text-left border-collapse table-fixed min-w-[1200px]">
          <thead className="sticky top-0 z-20">
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[70px]">S.No</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[260px]">Client Identity</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Tax Type</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Freq.</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Portal Creds</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px] text-center">Status</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[130px]">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredClients.length === 0 ? (
              <tr><td colSpan={8} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No Master Records Found</td></tr>
            ) : (
              filteredClients.map((client, idx) => (
                <tr key={client.id} className="hover:bg-indigo-50/20 transition-all group">
                  <td className="px-6 py-5 font-black text-slate-300 text-xs">{(idx + 1).toString().padStart(2, '0')}</td>
                  <td className="px-6 py-5">
                     <p className="font-black text-slate-900 uppercase truncate text-sm" title={client.legalName}>{client.legalName}</p>
                     <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest truncate mt-0.5">{client.tradeName || 'No Trade Name'}</p>
                  </td>
                  <td className="px-6 py-5">
                    <div className="flex items-center gap-2 group/gstin">
                      <span className="font-black text-indigo-600 font-mono tracking-widest uppercase text-xs">{client.gstProfile?.gstin}</span>
                      <button onClick={() => copyToClipboard(client.gstProfile?.gstin || '')} className="p-1 text-slate-300 hover:text-indigo-600 opacity-0 group-hover/gstin:opacity-100 transition-all">
                        <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg>
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-widest border ${client.gstProfile?.regType === 'Regular' ? 'bg-blue-50 text-blue-600 border-blue-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                      {client.gstProfile?.regType}
                    </span>
                  </td>
                  <td className="px-6 py-5 text-[11px] font-black text-slate-500 uppercase">{client.gstProfile?.filingFreq}</td>
                  <td className="px-6 py-5">
                    <div className="space-y-0.5">
                      <p className="text-[10px] font-black text-slate-700">{client.gstProfile?.username}</p>
                      <p className="text-[8px] font-bold text-slate-300 font-mono tracking-tighter uppercase">Password Secured</p>
                    </div>
                  </td>
                  <td className="px-6 py-5 text-center">
                    <span className={`px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${client.status === 'Active Filing' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-50 text-slate-400'}`}>
                      {client.status === 'Active Filing' ? 'Active' : 'Case Only'}
                    </span>
                  </td>
                  <td className="px-6 py-5 text-right whitespace-nowrap">
                    <div className="flex items-center justify-end gap-2">
                       <button onClick={() => { setSelectedClient(client); setIsEditModalOpen(true); }} className="h-8 w-8 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                       </button>
                       <button onClick={() => handleDelete(client)} className="h-8 w-8 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-red-600 hover:bg-white transition-all flex items-center justify-center shadow-sm">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                       </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      <GSTClientFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={handleDataChange} initialData={selectedClient} />
    </div>
  );
};

