import React, { useState, useEffect } from 'react';
import { Client, ConstitutionType, GstStatus, GstRegType, GstFilingFreq, ClientStatus, JurisdictionType } from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const STATE_CODES: Record<string, string> = {
  '01': 'Jammu & Kashmir', '02': 'Himachal Pradesh', '03': 'Punjab', '04': 'Chandigarh',
  '05': 'Uttarakhand', '06': 'Haryana', '07': 'Delhi', '08': 'Rajasthan',
  '09': 'Uttar Pradesh', '10': 'Bihar', '22': 'Chhattisgarh', '24': 'Gujarat',
  '27': 'Maharashtra', '33': 'Tamil Nadu'
};

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'basic' | 'filing' | 'admin'>('basic');
  const [derivedState, setDerivedState] = useState<string>('');

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '', tradeName: '', email: '', mobile: '', status: 'Active Filing',
    gstProfile: {
      gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
      regDate: '', regType: 'Regular', filingFreq: 'Monthly',
      constitution: 'Proprietorship', stakeholders: [],
      accountantName: '', accountantMobile: '', address: '',
      jurisdictionType: 'State', sector: '', range: ''
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
      if (initialData.gstProfile?.gstin) {
        const code = initialData.gstProfile.gstin.substring(0, 2);
        setDerivedState(STATE_CODES[code] || 'Unknown State');
      }
    } else {
      setFormData({
        legalName: '', tradeName: '', email: '', mobile: '', status: 'Active Filing',
        gstProfile: {
          gstin: '', pan: '', username: '', password: '', gstStatus: 'Active',
          regDate: '', regType: 'Regular', filingFreq: 'Monthly',
          constitution: 'Proprietorship', stakeholders: [],
          accountantName: '', accountantMobile: '', address: '',
          jurisdictionType: 'State', sector: '', range: ''
        },
        bankDetails: { bankName: '', accountNo: '', ifsc: '' },
        remarks: ''
      });
      setDerivedState('');
    }
    setError(null);
    setActiveTab('basic');
  }, [initialData, isOpen]);

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().trim().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';

    // Power-User Logic: Auto-derive PAN from GSTIN (Positions 3-12)
    if (gstin.length >= 12) {
      pan = gstin.substring(2, 12);
    }

    // Auto-derive State
    if (gstin.length >= 2) {
      const code = gstin.substring(0, 2);
      setDerivedState(STATE_CODES[code] || 'Code: ' + code);
    } else {
      setDerivedState('');
    }

    setFormData(prev => ({
      ...prev,
      gstProfile: { ...prev.gstProfile!, gstin, pan }
    }));

    if (error && gstin.length < 15) setError(null);
  };

  const handleSave = async () => {
    setError(null);
    if (!formData.legalName) return setError("Entity Legal Name is mandatory.");
    if (formData.gstProfile?.gstin?.length !== 15) return setError("GSTIN must be exactly 15 characters.");

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Vault sync failed.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95">
        <div className="px-8 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50 shrink-0 rounded-t-[2rem]">
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">GST Master Record</h2>
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.3em] mt-1.5">Vault Identification Protocol</p>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-slate-200 rounded-2xl transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
          </button>
        </div>

        <div className="flex border-b border-slate-100 bg-white shrink-0 overflow-x-auto no-scrollbar px-4">
           {[
             { id: 'basic', label: '1. Identity' },
             { id: 'filing', label: '2. Config' },
             { id: 'admin', label: '3. Admin' }
           ].map((t) => (
             <button key={t.id} onClick={() => setActiveTab(t.id as any)} 
               className={`py-6 px-8 text-[11px] font-black uppercase tracking-widest transition-all border-b-4 whitespace-nowrap ${activeTab === t.id ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
               {t.label}
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-10 no-scrollbar">
          {error && <div className="p-4 bg-rose-50 text-rose-600 rounded-2xl font-black border border-rose-100 text-[10px] uppercase tracking-[0.2em] animate-in shake duration-300">{error}</div>}

          {activeTab === 'basic' && (
            <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-300">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="md:col-span-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2.5 block ml-1 tracking-widest">GSTIN Identifier</label>
                    <div className="relative group">
                       <input 
                         autoFocus
                         className="w-full bg-slate-50 border border-slate-200 p-5 rounded-2xl font-black uppercase font-mono tracking-[0.25em] outline-none focus:ring-8 focus:ring-indigo-100 transition-all text-xl text-indigo-600" 
                         placeholder="22AAAAA0000A1Z5" 
                         value={formData.gstProfile?.gstin} 
                         onChange={e => handleGstinChange(e.target.value)} 
                       />
                       <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-3">
                          {derivedState && (
                            <span className="bg-white px-4 py-2 rounded-xl text-[10px] font-black uppercase border border-slate-100 shadow-sm text-slate-500 animate-in fade-in zoom-in">{derivedState}</span>
                          )}
                          {formData.gstProfile?.gstin?.length === 15 && (
                             <div className="h-8 w-8 rounded-full bg-emerald-500 text-white flex items-center justify-center shadow-lg shadow-emerald-200 animate-in zoom-in">
                                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                             </div>
                          )}
                       </div>
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-2.5 block ml-1 tracking-widest">Legal Name (As per PAN)</label>
                    <input className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold uppercase outline-none focus:border-indigo-400 focus:bg-white transition-all" value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} placeholder="Full Entity Name" />
