                        <button type="button" onClick={() => { navigator.clipboard.writeText(formData.gstProfile?.username || ''); window.open('https://services.gst.gov.in/services/login', '_blank'); }} className="bg-slate-100 p-3 rounded-2xl hover:bg-indigo-100 text-indigo-600 transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6" /></svg></button>
