                       <button onClick={() => removeStakeholder(s.id)} className="absolute top-4 right-4 h-8 w-8 bg-white border border-rose-100 text-rose-500 rounded-lg flex items-center justify-center shadow-sm hover:bg-rose-50 transition-all opacity-0 group-hover:opacity-100">
