import React, { useState, useEffect } from 'react';
import { Client, ITProfile, NatureOfWork, ClientStatus } from '../../types.ts';
import { api } from '../../services/api.ts';

interface ITClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const ITClientFormModal: React.FC<ITClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [existingClients, setExistingClients] = useState<Client[]>([]);
  const [isDataLinked, setIsDataLinked] = useState(false);

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    mobile: '',
    email: '',
    status: 'Active',
    itProfile: {
      pan: '',
      username: '',
      password: '',
      category: 'Individual',
      fatherName: '',
      dob: '',
      natureOfWork: 'Salaried',
      employmentType: 'Private',
      businessName: '',
      advisoryWork: {
        itrFiling: true,
        taxAudit: false,
        balanceSheet: false,
        appeals: false
      }
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (isOpen) {
      api.getClients().then(setExistingClients);
      if (initialData) {
        setFormData(initialData);
        setIsDataLinked(false);
      } else {
        resetForm();
      }
    }
  }, [isOpen, initialData]);

  const resetForm = () => {
    setFormData({
      legalName: '', mobile: '', email: '', status: 'Active',
      itProfile: {
        pan: '', username: '', password: '', category: 'Individual',
        fatherName: '', dob: '', natureOfWork: 'Salaried',
        employmentType: 'Private', businessName: '',
        advisoryWork: { itrFiling: true, taxAudit: false, balanceSheet: false, appeals: false }
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
    setIsDataLinked(false);
  };

  // --- Intelligence: Cross-Profile Linkage ---
  const handlePanChange = (val: string) => {
    const pan = val.toUpperCase().trim().slice(0, 10);
    setFormData(prev => ({
      ...prev,
      itProfile: { ...prev.itProfile!, pan, username: pan }
    }));

    // Trigger linkage lookup only in "Add" mode when PAN is complete
    if (!initialData && pan.length === 10) {
      const gstMatch = existingClients.find(c => 
        (c.gstProfile?.pan === pan || c.gstProfile?.gstin?.substring(2, 12) === pan) && !c.itProfile
      );

      if (gstMatch) {
        setFormData(prev => ({
          ...prev,
          legalName: gstMatch.legalName,
          mobile: gstMatch.mobile,
          email: gstMatch.email,
          // If the existing client record doesn't have an IT profile, we are augmenting it
          id: gstMatch.id 
        }));
        setIsDataLinked(true);
      } else {
        setIsDataLinked(false);
      }
    }
  };

  const handleSave = async () => {
    setError(null);
    const profile = formData.itProfile!;

    // Validations
    if (!formData.legalName) return setError("Full Legal Name is required.");
    const panRegex = /[A-Z]{5}[0-9]{4}[A-Z]{1}/;
    if (!panRegex.test(profile.pan)) return setError("Invalid PAN format (Expected: ABCDE1234F).");
    if (formData.mobile && !/^\d{10}$/.test(formData.mobile)) return setError("Mobile number must be 10 digits.");

    // Check for duplicate PAN in IT vault
    const isDuplicate = existingClients.some(c => 
      c.itProfile?.pan === profile.pan && c.id !== (initialData?.id || formData.id)
    );
    if (isDuplicate) return setError(`PAN ${profile.pan} is already registered in the IT vault.`);

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Cloud vault sync failed.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

