export default GSTClientFormModal;

import React, { useState, useEffect } from 'react';
import { Client, ITProfile, NatureOfWork, ClientStatus } from '../../types.ts';
import { api } from '../../services/api.ts';

interface ITClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
  context?: 'it';
}

const ITClientFormModal: React.FC<ITClientFormModalProps> = ({ isOpen, onClose, onSave, initialData, context = 'it' }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [existingClients, setExistingClients] = useState<Client[]>([]);
  const [isDataLinked, setIsDataLinked] = useState(false);

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    mobile: '',
    email: '',
    status: 'Active',
    itProfile: {
      pan: '',
      username: '',
      password: '',
      category: 'Individual',
      fatherName: '',
      dob: '',
      natureOfWork: 'Salaried',
      employmentType: 'Private',
      businessName: '',
      advisoryWork: {
        itrFiling: true,
        taxAudit: false,
        balanceSheet: false,
        appeals: false
      }
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (isOpen) {
      api.getClients().then(setExistingClients);
      if (initialData) {
        setFormData(initialData);
        setIsDataLinked(false);
      } else {
        resetForm();
      }
    }
  }, [isOpen, initialData]);

  const resetForm = () => {
    setFormData({
      legalName: '', mobile: '', email: '', status: 'Active',
      itProfile: {
        pan: '', username: '', password: '', category: 'Individual',
        fatherName: '', dob: '', natureOfWork: 'Salaried',
        employmentType: 'Private', businessName: '',
        advisoryWork: { itrFiling: true, taxAudit: false, balanceSheet: false, appeals: false }
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
    setIsDataLinked(false);
  };

  const handlePanChange = (val: string) => {
    const pan = val.toUpperCase().trim().slice(0, 10);
    setFormData(prev => ({
      ...prev,
      itProfile: { ...prev.itProfile!, pan, username: pan }
    }));

    // Smart Linkage: Auto-populate if PAN matches a GST profile
    if (!initialData && pan.length === 10) {
      const gstMatch = existingClients.find(c => 
        (c.gstProfile?.pan === pan || c.gstProfile?.gstin?.substring(2, 12) === pan) && !c.itProfile
      );

      if (gstMatch) {
        setFormData(prev => ({
          ...prev,
          legalName: gstMatch.legalName,
          mobile: gstMatch.mobile,
          email: gstMatch.email,
          id: gstMatch.id 
        }));
        setIsDataLinked(true);
      } else {
        setIsDataLinked(false);
      }
    }
  };

  const handleSave = async () => {
    setError(null);
    const profile = formData.itProfile!;

    const panRegex = /[A-Z]{5}[0-9]{4}[A-Z]{1}/;
    if (!formData.legalName) return setError("Principal Legal Name is required.");
    if (!panRegex.test(profile.pan)) return setError("Invalid PAN format (e.g. ABCDE1234F).");
    if (formData.mobile && !/^\d{10}$/.test(formData.mobile)) return setError("Mobile must be 10 digits.");

    const isDuplicate = existingClients.some(c => 
      c.itProfile?.pan === profile.pan && c.id !== (initialData?.id || formData.id)
    );
    if (isDuplicate) return setError(`PAN ${profile.pan} is already archived in IT records.`);

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Cloud vault synchronization failed.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 overflow-hidden animate-in fade-in duration-300">
      <div className="w-full max-w-4xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden border border-slate-200">

        <header className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50 shrink-0">
          <div className="flex items-center gap-4">
             <div className="h-12 w-12 rounded-2xl bg-indigo-600 flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
             </div>
             <div>
