                            <div 
                              className={`w-full rounded-lg md:rounded-xl transition-all duration-1000 group-hover:bg-indigo-600 ${h > 80 ? 'bg-rose-500/20' : h > 50 ? 'bg-indigo-600/10' : 'bg-slate-200'}`} 
                              style={{ height: `${h}%` }} 
