const Invoices = lazy(() => import('../Administration/invoice/Invoices.tsx'));
const AddInvoice = lazy(() => import('../Administration/invoice/addinvoice.tsx'));
const PaymentReceived = lazy(() => import('../Administration/invoice/PaymentReceived.tsx'));
const DueDateSetting = lazy(() => import('../Administration/DueDateSetting.tsx'));
const Setting = lazy(() => import('../Administration/Setting.tsx'));
const Trash = lazy(() => import('../Administration/Trash.tsx'));

const VIEW_LABELS: Record<string, { label: string; desc: string }> = {
  'dashboard': { label: 'Mission Control', desc: 'Holistic performance and firm-wide intelligence.' },
  'gst-portfolio': { label: 'GST Portfolio', desc: 'Secure repository for entity GST credentials.' },
  'it-portfolio': { label: 'IT Portfolio', desc: 'Consolidated income tax identifier vault.' },
};

const Dashboard: React.FC = () => {
  const { user, token } = useAuth();
  const isOnline = useOffline();
  const { installPrompt, triggerInstall } = usePWA();
  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const [viewExtra, setViewExtra] = useState<any>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Data State
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [litigation, setLitigation] = useState<LitigationRecord[]>([]);
  const [miscWork, setMiscWork] = useState<any[]>([]);

  // Form Modals
  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isItModalOpen, setIsItModalOpen] = useState(false);

  // Period Filters for Dashboard Boxes
  const def = getDefaultPeriod();
  const [monthlyFilter, setMonthlyFilter] = useState({ year: def.year, month: def.month });
  const [quarterlyFilter, setQuarterlyFilter] = useState({ year: def.year, quarter: def.quarter });
  const [compositionFilter, setCompositionFilter] = useState({ year: def.quarterYear, quarter: def.quarter });
  const [annualFilter, setAnnualFilter] = useState({ year: def.year });
  const [itrFilter, setItrFilter] = useState({ ay: def.year });

  const activeConfig = useMemo(() => VIEW_LABELS[activeView] || { label: 'Vault Module', desc: 'Secured practitioner data.' }, [activeView]);

  const loadData = useCallback(async () => {
    if (!token) return;
    try {
      const summary = await api.getDashboardSummary();
      setClients(summary.clients);
      setInvoices(summary.invoices);
      setLitigation(summary.litigation);
      setMiscWork(summary.work);
    } catch (err) { console.error('Dashboard Sync Failed:', err); } finally { setIsInitialLoad(false); }
  }, [token]);

  useEffect(() => {
    if (isOnline) { loadData(); socketService.connect(); }
    return () => socketService.disconnect();
  }, [isOnline, loadData]);

  const handleViewChange = (view: ActiveView, extra?: any) => {
    setActiveView(view);
    setViewExtra(extra || null);
    setIsSidebarOpen(false);
    window.scrollTo(0, 0);
  };

  // Helper for Getting Status Counts from LocalStorage (Syncs with Return Pages)
  const getFilingCounts = (type: 'monthly' | 'quarterly' | 'composition' | 'gstr4' | 'gstr9' | 'itr' | 'audit', periodKey: string) => {
    const keys: Record<string, string> = {
      monthly: 'clientify_monthly_filing_v3',
      quarterly: 'clientify_quarterly_filing_v3',
      composition: 'clientify_composition_filing_v3',
      gstr4: 'clientify_gstr4_filing_v1',
      gstr9: 'clientify_gstr9_filing_data_v2',
      itr: 'clientify_itr_filing_data_v2',
      audit: 'clientify_audit_fin_data_v3'
    };
    const storageKey = keys[type];
    const saved = localStorage.getItem(storageKey);
    const data = saved ? JSON.parse(saved) : {};
    const periodData = data[periodKey] || {};

    // Total should be based on applicable clients
    let total = 0;
    let filed = 0;

    if (type === 'monthly') {
      const applicable = clients.filter(c => c.status === 'Active Filing' && c.gstProfile?.regType === 'Regular' && c.gstProfile?.filingFreq === 'Monthly');
      total = applicable.length;
      filed = applicable.filter(c => periodData[c.id]?.r1 && periodData[c.id]?.r3b).length;
    } else if (type === 'quarterly') {
      const applicable = clients.filter(c => c.status === 'Active Filing' && c.gstProfile?.regType === 'Regular' && c.gstProfile?.filingFreq === 'Quarterly');
      total = applicable.length;
      filed = applicable.filter(c => periodData[c.id]?.r1 && periodData[c.id]?.r3b).length;
    } else if (type === 'composition') {
      const applicable = clients.filter(c => c.status === 'Active Filing' && c.gstProfile?.regType === 'Composition');
      total = applicable.length;
      filed = applicable.filter(c => periodData[c.id]?.cmp08).length;
    } else if (type === 'itr') {
      const applicable = clients.filter(c => !!c.itProfile && c.status.includes('Active'));
      total = applicable.length;
      filed = applicable.filter(c => periodData[c.id]?.filed).length;
    } else {
      // Annual / Audit usually has a watchlist
      filed = Object.values(periodData).filter((v: any) => v.filed || v.auditFiled).length;
      total = Object.keys(periodData).length;
    }

    return { total, filed, pending: Math.max(0, total - filed) };
  };

  // Helper for Global Due Dates
  const getDueDate = (moduleId: string, period: string, year: string) => {
    const saved = localStorage.getItem('clientify_global_compliance_dates_v1');
    if (!saved) return '---';
    const dates = JSON.parse(saved);
    const key = `${moduleId}_${year}_${period}`;
    const val = dates[key];
    if (!val) return '---';
    return val.split('-').reverse().join('/');
  };

  const DashboardCard = ({ 
    title, 
    countObj, 
    viewId, 
    icon, 
    color, 
    filters, 
    dueDate,
    action
  }: { 
    title: string; 
    countObj?: { total: number; filed?: number; pending?: number }; 
    viewId: string; 
    icon: React.ReactNode; 
    color: string;
    filters?: React.ReactNode;
    dueDate?: string;
    action?: { label: string; onClick: (e: React.MouseEvent) => void; color: string; }
  }) => (
    <div 
      onClick={() => handleViewChange(viewId)}
      className="group relative flex flex-col bg-white rounded-[2rem] border border-slate-200 shadow-sm hover:border-indigo-400 hover:shadow-xl transition-all duration-500 cursor-pointer overflow-hidden p-6 md:p-8"
    >
      <div className="flex items-start justify-between mb-6">
        <div className={`h-12 w-12 rounded-2xl ${color} flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform`}>
           <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">{icon}</svg>
        </div>
        {countObj && (
           <div className="text-right">
              <p className="text-2xl font-black text-slate-900 leading-none">{countObj.total}</p>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Total Records</p>
           </div>
        )}
      </div>

      <div className="mb-6">
        <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight group-hover:text-indigo-600 transition-colors">{title}</h3>
        {dueDate && <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mt-1">Due: {dueDate}</p>}
      </div>

      {filters && <div className="mb-6 flex flex-wrap gap-2" onClick={e => e.stopPropagation()}>{filters}</div>}

      {countObj && countObj.filed !== undefined && (
        <div className="flex items-center gap-4 mb-6">
           <div className="flex-1 bg-emerald-50 rounded-xl p-3 border border-emerald-100">
              <p className="text-emerald-700 text-sm font-black">{countObj.filed}</p>
              <p className="text-[8px] font-black text-emerald-600 uppercase">Filed</p>
           </div>
           <div className="flex-1 bg-amber-50 rounded-xl p-3 border border-amber-100">
              <p className="text-amber-700 text-sm font-black">{countObj.pending}</p>
              <p className="text-[8px] font-black text-amber-600 uppercase">Pending</p>
           </div>
        </div>
      )}

      <div className="mt-auto flex items-center justify-between gap-4">
         {action ? (
            <button 
              onClick={action.onClick}
              className={`flex-1 py-3.5 rounded-xl font-black uppercase text-[10px] tracking-widest text-white shadow-md transition-all active:scale-95 ${action.color} hover:brightness-90`}
            >
              {action.label}
            </button>
         ) : (
            <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest group-hover:translate-x-2 transition-transform">Enter Module →</span>
         )}
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="max-w-full mx-auto space-y-10 animate-in fade-in duration-700 pb-32">
            {installPrompt && <InstallBanner onInstall={triggerInstall} />}

            {/* PORTFOLIO CLUSTER */}
            <section>
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6 flex items-center gap-4">Portfolio Management <div className="h-px flex-1 bg-slate-100" /></h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                <DashboardCard 
                  title="GST Portfolio" 
                  countObj={{ total: clients.filter(c => !!c.gstProfile).length }}
                  viewId="gst-portfolio"
                  color="bg-indigo-600"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2-2h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011-1v5m-4 0h4" />}
                  action={{ label: "Add GST Client", color: "bg-slate-900", onClick: (e) => { e.stopPropagation(); setIsGstModalOpen(true); } }}
                />
                <DashboardCard 
                  title="IT Portfolio" 
                  countObj={{ total: clients.filter(c => !!c.itProfile).length }}
                  viewId="it-portfolio"
                  color="bg-emerald-600"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />}
                  action={{ label: "Add IT Client", color: "bg-slate-900", onClick: (e) => { e.stopPropagation(); setIsItModalOpen(true); } }}
                />
              </div>
            </section>

            {/* RETURN COMPLIANCE CLUSTER */}
            <section>
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6 flex items-center gap-4">Return Compliance <div className="h-px flex-1 bg-slate-100" /></h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">

                {/* Monthly Filing */}
                <DashboardCard 
                  title="Monthly Filing" 
                  viewId="compliance-monthly"
                  color="bg-indigo-500"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />}
                  dueDate={getDueDate('monthly_r1', monthlyFilter.month, monthlyFilter.year)}
                  filters={
                    <>
                      <select value={monthlyFilter.year} onChange={e => setMonthlyFilter({...monthlyFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                      <select value={monthlyFilter.month} onChange={e => setMonthlyFilter({...monthlyFilter, month: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{FY_MONTHS.map(m => <option key={m} value={m}>{m}</option>)}</select>
                    </>
                  }
                  countObj={getFilingCounts('monthly', `${monthlyFilter.year}_${monthlyFilter.month}`)}
                />

                {/* Quarterly Filing */}
                <DashboardCard 
                  title="Quarterly Filing" 
                  viewId="compliance-quarterly"
                  color="bg-blue-500"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />}
                  dueDate={getDueDate('quarterly_iff', quarterlyFilter.quarter, quarterlyFilter.year)}
                  filters={
                    <>
                      <select value={quarterlyFilter.year} onChange={e => setQuarterlyFilter({...quarterlyFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                      <select value={quarterlyFilter.quarter} onChange={e => setQuarterlyFilter({...quarterlyFilter, quarter: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{FY_QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}</select>
                    </>
                  }
                  countObj={getFilingCounts('quarterly', `${quarterlyFilter.year}_${quarterlyFilter.quarter}`)}
                />

                {/* Composition */}
                <DashboardCard 
                  title="Composition" 
                  viewId="compliance-composition"
                  color="bg-amber-500"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />}
                  dueDate={getDueDate('composition_cmp08', compositionFilter.quarter, compositionFilter.year)}
                  filters={
                    <>
                      <select value={compositionFilter.year} onChange={e => setCompositionFilter({...compositionFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                      <select value={compositionFilter.quarter} onChange={e => setCompositionFilter({...compositionFilter, quarter: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{FY_QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}</select>
                    </>
                  }
                  countObj={getFilingCounts('composition', `${compositionFilter.year}_${compositionFilter.quarter}`)}
                />

                {/* ITR Returns */}
                <DashboardCard 
                  title="ITR Returns" 
                  viewId="compliance-itr"
                  color="bg-emerald-500"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" />}
                  dueDate={getDueDate('itr_return', 'Annual', itrFilter.ay)}
                  filters={
                    <>
                      <span className="text-[9px] font-black text-slate-400 uppercase mt-1.5 mr-1">AY:</span>
                      <select value={itrFilter.ay} onChange={e => setItrFilter({...itrFilter, ay: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                    </>
                  }
                  countObj={getFilingCounts('itr', itrFilter.ay)}
                />

                {/* GSTR-4 */}
                <DashboardCard 
                  title="GSTR-4 (Annual)" 
                  viewId="compliance-gstr4"
                  color="bg-rose-500"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />}
                  dueDate={getDueDate('annual_gstr4', 'Annual', annualFilter.year)}
                  filters={
                    <select value={annualFilter.year} onChange={e => setAnnualFilter({...annualFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                  }
                  countObj={getFilingCounts('gstr4', annualFilter.year)}
                />

                {/* GSTR-9/9C */}
                <DashboardCard 
                  title="GSTR-9/9C" 
                  viewId="compliance-gstr9"
                  color="bg-indigo-700"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />}
                  dueDate={getDueDate('annual_gstr9', 'Annual', annualFilter.year)}
                  filters={
                    <select value={annualFilter.year} onChange={e => setAnnualFilter({...annualFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                  }
                  countObj={getFilingCounts('gstr9', annualFilter.year)}
                />

                {/* TAX AUDIT */}
                <DashboardCard 
                  title="Audit & Financials" 
                  viewId="compliance-taxaudit"
                  color="bg-slate-800"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />}
                  dueDate={getDueDate('audit_tax', 'Annual', annualFilter.year)}
                  filters={
                    <select value={annualFilter.year} onChange={e => setAnnualFilter({...annualFilter, year: e.target.value})} className="bg-slate-50 border-none rounded-lg px-2 py-1 text-[9px] font-black uppercase outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
                  }
                  countObj={getFilingCounts('audit', annualFilter.year)}
                />
              </div>
            </section>

            {/* LITIGATION & MISC */}
            <section>
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6 flex items-center gap-4">Litigation & Ops <div className="h-px flex-1 bg-slate-100" /></h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                <DashboardCard 
                  title="Invoices" 
                  viewId="admin-invoices"
                  color="bg-violet-600"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />}
                  countObj={{ total: invoices.length }}
                  action={{ label: "Create Invoice", color: "bg-slate-900", onClick: (e) => { e.stopPropagation(); handleViewChange('admin-add-invoice'); } }}
                />
                <DashboardCard 
                  title="GST Notices" 
                  viewId="lit-notice-pending"
                  color="bg-rose-600"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />}
                  countObj={{ total: litigation.filter(l => l.category === 'Notice' && l.status === 'Pending').length }}
                />
                <DashboardCard 
                  title="Misc Work" 
                  viewId="misc-work"
                  color="bg-blue-600"
                  icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />}
                  countObj={{ total: miscWork.filter(w => w.status !== 'Completed').length }}
                />
              </div>
            </section>
          </div>
        );
      case 'gst-portfolio': return <GSTPortfolio />;
      case 'it-portfolio': return <ITPortfolio />;
      case 'compliance-monthly': return <MonthlyFiling />;
      case 'compliance-quarterly': return <QuarterlyFiling />;
      case 'compliance-composition': return <CompositionFiling />;
      case 'compliance-gstr4': return <GSTR4 />;
      case 'compliance-gstr9': return <GSTR9_9C />;
      case 'compliance-itr': return <ITRReturn />;
      case 'compliance-taxaudit': return <TAXAudit />;
      case 'lit-notice-pending': return <NoticePending />;
      case 'lit-notice-filed': return <NoticeFiled />;
      case 'lit-notice-drop': return <NoticeDrop />;
      case 'lit-notice-demand': return <NoticeDemand />;
      case 'lit-appeal-pending': return <AppealPending />;
      case 'lit-appeal-filed': return <AppealFiled />;
      case 'lit-appeal-drop': return <AppealDrop />;
      case 'lit-appeal-demand': return <AppealDemand />;
      case 'lit-tribunal-pending': return <TribunalPending />;
      case 'lit-tribunal-filed': return <TribunalFiled />;
      case 'lit-tribunal-drop': return <TribunalDrop />;
      case 'lit-tribunal-demand': return <TribunalDemand />;
      case 'lit-hc-pending': return <CourtPending />;
      case 'lit-hc-filed': return <CourtFiled />;
      case 'lit-hc-drop': return <CourtDrop />;
      case 'lit-hc-demand': return <CourtDemand />;
      case 'misc-gst-reg': return <GSTRegistration />;
      case 'misc-food-lic': return <FoodLicenses />;
      case 'misc-msme': return <MSMERegistration />;
      case 'misc-work': return <Miscellaneouswork />;
      case 'reminders': return <Reminders />;
      case 'messenger': return <Messenger />;
      case 'admin-invoices': return <Invoices onViewChange={handleViewChange} />;
      case 'admin-add-invoice': return <AddInvoice onBack={() => handleViewChange('admin-invoices')} editingInvoice={viewExtra} />;
      case 'admin-payments': return <PaymentReceived onViewChange={handleViewChange} />;
      case 'admin-duedates': return <DueDateSetting />;
      case 'settings': return <Setting />;
      case 'trash': return <Trash />;
      default: return <div className="p-20 text-center text-slate-300 font-black uppercase tracking-widest">Invalid View ID</div>;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#fcfdfe] relative">
      <Sidebar activeView={activeView} onViewChange={handleViewChange} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header 
          isConnected={isOnline} 
          currentUser={user} 
          onMenuClick={() => setIsSidebarOpen(true)} 
          activeViewLabel={activeConfig.label} 
          activeViewDescription={activeConfig.desc} 
        />
        <div className="flex-1 flex flex-col min-h-0 px-4 md:px-6 lg:px-12 pt-6 md:pt-8 pb-12 overflow-y-auto no-scrollbar scroll-smooth">
          {isInitialLoad && activeView === 'dashboard' ? <Loader /> : (
            <Suspense fallback={<Loader />}>{renderContent()}</Suspense>
          )}
        </div>
      </main>
      <CommandPalette isOpen={isPaletteOpen} onClose={() => setIsPaletteOpen(false)} onViewChange={handleViewChange} />

      {/* Dashboard Specific Form Modals */}
      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => loadData()} />
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => loadData()} />
    </div>
  );
};

