                     >
                        {child.label}
                     </button>
                   ))}
                </div>
             )}
          </div>
        )}

        {/* Expanded Mode Sub-items */}
        {!isCollapsed && hasChildren && isExpanded && (
          <div className="mt-1 space-y-1 border-l-2 border-slate-100 ml-6 pl-2 animate-in slide-in-from-top-2 duration-200">
