import React, { useState, useEffect } from 'react';
import { 
  Client, 
  ConstitutionType, 
  GstRegType, 
  GstFilingFreq, 
  ClientStatus, 
  Stakeholder,
  GstStatus
} from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const defaultStakeholder = (): Stakeholder => ({
    id: Math.random().toString(36).substr(2, 9),
    name: '',
    mobile: '',
    pan: '',
    itPassword: '',
    address: ''
  });

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active',
    gstProfile: {
      gstin: '',
      pan: '',
      username: '',
      password: '',
      gstStatus: 'Active',
      regDate: '',
      cancelDate: '',
      regType: 'Regular',
      filingFreq: 'Monthly',
      constitution: 'Proprietorship',
      stakeholders: [defaultStakeholder()],
      accountantName: '',
      accountantMobile: ''
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setFormData({
          ...initialData,
          gstProfile: {
            ...initialData.gstProfile!,
            cancelDate: initialData.gstProfile?.cancelDate || ''
          }
        });
      } else {
        resetForm();
      }
    }
  }, [isOpen, initialData]);

  const resetForm = () => {
    setFormData({
      legalName: '',
      tradeName: '',
      email: '',
      mobile: '',
      status: 'Active',
      gstProfile: {
        gstin: '',
        pan: '',
        username: '',
        password: '',
        gstStatus: 'Active',
        regDate: '',
        cancelDate: '',
        regType: 'Regular',
        filingFreq: 'Monthly',
        constitution: 'Proprietorship',
        stakeholders: [defaultStakeholder()],
        accountantName: '',
        accountantMobile: ''
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
  };

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().trim().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';
    if (gstin.length >= 10) pan = gstin.substring(2, 12);

    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        gstin,
        pan,
        stakeholders: prev.gstProfile!.stakeholders.map((s, idx) => 
          idx === 0 ? { ...s, pan: pan } : s
        )
      }
    }));
  };

  const updateStakeholder = (id: string, field: keyof Stakeholder, val: string) => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        stakeholders: prev.gstProfile!.stakeholders.map(s => 
          s.id === id ? { ...s, [field]: val } : s
        )
      }
    }));
  };

  const handleSave = async () => {
    setError(null);
    if (!formData.tradeName) return setError("Trade Name is mandatory.");
    if (formData.gstProfile?.gstin?.length !== 15) return setError("Valid 15-char GSTIN required.");

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Archive failed.");
    } finally {
      setIsSaving(false);
    }
  };

  const copyAndPortal = () => {
    if (!formData.gstProfile?.username) return;
    navigator.clipboard.writeText(formData.gstProfile.username);
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 overflow-hidden animate-in fade-in duration-300">
      <div className="w-full max-w-4xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">

        <header className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50 shrink-0">
          <div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase leading-none">GST Entity Profile</h2>
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mt-2">Professional Compliance Matrix</p>
          </div>
          <button onClick={onClose} className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-slate-100 transition-all">
            <svg className="h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto no-scrollbar p-8 space-y-10">
          {error && <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl text-[10px] font-black uppercase text-rose-600 text-center">{error}</div>}

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Client Status</label>
              <select className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})}>
                <option value="Active">Active</option>
                <option value="Litigation">Litigation</option>
                <option value="Inactive">Inactive</option>
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Trade Name</label>
              <input className="w-full bg-slate-50 border-none rounded-xl p-3 font-black text-xs uppercase" value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} placeholder="BUSINESS NAME" />
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Business Type</label>
              <select className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.constitution} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, constitution: e.target.value as any}})}>
                <option value="Proprietorship">Proprietorship</option>
                <option value="Partnership">Partnership</option>
                <option value="HUF">HUF</option>
                <option value="Company">Company</option>
                <option value="Other">Other</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-indigo-50/30 p-6 rounded-2xl border border-indigo-100/50">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-indigo-400 tracking-widest ml-1">GSTIN Identifier</label>
              <div className="flex gap-2">
                <input className="w-full bg-white border border-indigo-100 rounded-xl p-3 font-black uppercase font-mono tracking-widest text-xs outline-none focus:border-indigo-600" value={formData.gstProfile?.gstin} onChange={e => handleGstinChange(e.target.value)} placeholder="GSTIN" />
                <button type="button" onClick={() => window.open(`https://services.gst.gov.in/services/searchtp?gstin=${formData.gstProfile?.gstin}`, '_blank')} className="bg-indigo-600 text-white p-2.5 rounded-xl"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></button>
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-indigo-400 tracking-widest ml-1">Portal User ID</label>
              <div className="flex gap-2">
                <input className="w-full bg-white border border-indigo-100 rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.username} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, username: e.target.value}})} placeholder="Login ID" />
                <button type="button" onClick={() => { navigator.clipboard.writeText(formData.gstProfile?.username || ''); alert('ID Copied'); }} className="bg-slate-100 text-slate-600 p-2.5 rounded-xl"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1" /></svg></button>
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-indigo-400 tracking-widest ml-1">Password</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <input type={showPassword ? "text" : "password"} className="w-full bg-white border border-indigo-100 rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.password} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, password: e.target.value}})} placeholder="••••••••" />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300">{showPassword ? '🙈' : '👁️'}</button>
                </div>
                <button type="button" onClick={copyAndPortal} className="bg-slate-900 text-white px-4 rounded-xl text-[8px] font-black uppercase tracking-widest">Portal</button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">GSTIN Status</label>
              <select className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.gstStatus} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, gstStatus: e.target.value as GstStatus}})}>
                <option value="Active">Active</option>
                <option value="Suspended">Suspended</option>
                <option value="Closed">Closed</option>
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Taxpayer Type</label>
              <select className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.regType} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, regType: e.target.value as GstRegType}})}>
                <option value="Regular">Regular</option>
                <option value="Composition">Composition</option>
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Filing Frequency</label>
              <select className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.gstProfile?.filingFreq} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, filingFreq: e.target.value as GstFilingFreq}})}>
                <option value="Monthly">Monthly</option>
                <option value="Quarterly">Quarterly</option>
              </select>
            </div>
            <div className="space-y-1.5">
               <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Reg. Date</label>
               <input type="date" className="w-full bg-slate-50 border-none rounded-xl p-3 font-black text-[10px] uppercase" value={formData.gstProfile?.regDate} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, regDate: e.target.value}})} />
            </div>
            {formData.gstProfile?.gstStatus === 'Closed' && (
              <div className="space-y-1.5 animate-in slide-in-from-top-2">
                 <label className="text-[9px] font-black uppercase text-rose-400 tracking-widest ml-1">Closing Date</label>
                 <input type="date" className="w-full bg-rose-50/50 border-none rounded-xl p-3 font-black text-[10px] uppercase text-rose-600" value={formData.gstProfile?.cancelDate} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, cancelDate: e.target.value}})} />
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-1.5">
                <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Primary Mobile</label>
                <input className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs" value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value.replace(/\D/g, '')})} placeholder="9876543210" />
             </div>
             <div className="space-y-1.5">
                <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Entity Email</label>
                <input className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold text-xs lowercase" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="office@business.com" />
             </div>
          </div>

          <section className="space-y-4">
             <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 border-b border-slate-100 pb-2">Stakeholder Information</h4>
             {formData.gstProfile?.stakeholders.map((s, idx) => (
                <div key={s.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
                   <input className="bg-white border border-slate-200 rounded-lg p-2 text-xs font-black uppercase" value={s.name} onChange={e => updateStakeholder(s.id, 'name', e.target.value)} placeholder="Member Name" />
                   <input className="bg-white border border-slate-200 rounded-lg p-2 text-xs font-black uppercase font-mono" value={s.pan} onChange={e => updateStakeholder(s.id, 'pan', e.target.value.toUpperCase())} placeholder="PAN NO" />
                   <input className="bg-white border border-slate-200 rounded-lg p-2 text-xs font-black" value={s.itPassword} onChange={e => updateStakeholder(s.id, 'itPassword', e.target.value)} placeholder="IT Password" />
                </div>
             ))}
          </section>

          <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="space-y-4">
                <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 border-b border-slate-100 pb-2">Firm Contact (Accountant)</h4>
                <div className="grid grid-cols-2 gap-4">
                   <input className="bg-slate-50 border-none rounded-xl p-3 text-xs font-black uppercase" value={formData.gstProfile?.accountantName} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, accountantName: e.target.value}})} placeholder="Name" />
                   <input className="bg-slate-50 border-none rounded-xl p-3 text-xs font-black" value={formData.gstProfile?.accountantMobile} onChange={e => setFormData({...formData, gstProfile: {...formData.gstProfile!, accountantMobile: e.target.value}})} placeholder="Mobile" />
                </div>
             </div>
             <div className="space-y-4">
                <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 border-b border-slate-100 pb-2">Banking Sync</h4>
                <div className="grid grid-cols-3 gap-3">
                   <input className="bg-slate-50 border-none rounded-xl p-3 text-xs font-black uppercase" value={formData.bankDetails?.bankName} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, bankName: e.target.value}})} placeholder="Bank" />
                   <input className="bg-slate-50 border-none rounded-xl p-3 text-xs font-black" value={formData.bankDetails?.accountNo} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, accountNo: e.target.value}})} placeholder="A/C" />
                   <input className="bg-slate-50 border-none rounded-xl p-3 text-xs font-black uppercase" value={formData.bankDetails?.ifsc} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, ifsc: e.target.value.toUpperCase()}})} placeholder="IFSC" />
                </div>
             </div>
          </section>

          <div className="space-y-1.5">
             <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest ml-1">Internal Remarks</label>
             <textarea className="w-full bg-slate-50 border-none rounded-xl p-4 font-bold text-xs h-24" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Office notes..." />
          </div>
        </div>

        <footer className="px-8 py-6 border-t border-slate-100 bg-slate-50 flex items-center justify-end gap-3 shrink-0">
           <button onClick={onClose} className="px-6 py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Discard</button>
           <button onClick={handleSave} disabled={isSaving} className="bg-indigo-600 text-white font-black uppercase tracking-[0.2em] text-[10px] px-10 py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98] disabled:opacity-50">
             {isSaving ? 'Encrypting...' : 'Archive Profile'}
           </button>
        </footer>
      </div>
    </div>
  );
};

export default GSTClientFormModal;

export interface Message {
