import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, GstStatus, ClientStatus } from '../../types.ts';
import { api } from '../../services/api.ts';
import GSTClientFormModal from '../Clientform/GSTClientFormModal.tsx';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  onDataChange?: () => void;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);

  // Login Tool Box State
  const [isLoginBoxOpen, setIsLoginBoxOpen] = useState(false);
  const [loginToolClient, setLoginToolClient] = useState<Client | null>(null);
  const [showLoginPass, setShowLoginPass] = useState(false);
  const [isEditingLoginPass, setIsEditingLoginPass] = useState(false);
  const [tempPass, setTempPass] = useState('');

  // Actions Menu State
  const [activeActionsId, setActiveActionsId] = useState<string | null>(null);
  const actionsRef = useRef<HTMLDivElement>(null);

  const fetch = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    } catch (err) { console.error("Fetch failed", err); } finally { setIsLoading(false); }
  };

  useEffect(() => { fetch(); }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (actionsRef.current && !actionsRef.current.contains(event.target as Node)) {
        setActiveActionsId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleDataChange = () => {
    fetch();
    if (onDataChange) onDataChange();
  };

  const filteredClients = useMemo(() => {
    const s = externalSearch.toLowerCase();
    return clients.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s) ||
      (c.mobile && c.mobile.includes(s))
    );
  }, [clients, externalSearch]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const handleUpdatePassword = async () => {
    if (!loginToolClient || !tempPass.trim()) return;
    try {
      const updated = { ...loginToolClient, gstProfile: { ...loginToolClient.gstProfile!, password: tempPass } };
      await api.saveClient(updated);
      setLoginToolClient(updated as Client);
      setIsEditingLoginPass(false);
      fetch();
    } catch (err) { alert("Vault update failed."); }
  };

  if (isLoading) return (
    <div className="flex-1 flex flex-col items-center justify-center p-20 space-y-4">
       <div className="h-10 w-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin" />
       <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Accessing Secured Vault</p>
    </div>
  );

  return (
    <div className="flex-1 flex flex-col min-h-0">
      <div className="overflow-x-auto no-scrollbar flex-1">
        <table className="w-full text-left border-collapse table-fixed min-w-[1200px]">
          <thead className="sticky top-0 z-20">
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[70px]">S.No</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Trade Name</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[240px]">Legal Name</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Status</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px]">Relationship</th>
              <th className="px-6 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[120px]">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredClients.length === 0 ? (
              <tr><td colSpan={7} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No records found</td></tr>
            ) : (
              filteredClients.map((client, idx) => (
                <tr key={client.id} className="hover:bg-indigo-50/20 transition-all group">
                  <td className="px-6 py-5 font-black text-slate-300 text-xs">{(idx + 1).toString().padStart(2, '0')}</td>
                  <td className="px-6 py-5">
                     <p className="font-black text-slate-900 uppercase truncate text-sm" title={client.tradeName}>{client.tradeName || '---'}</p>
                  </td>
                  <td className="px-6 py-5">
                     <p className="font-bold text-slate-600 uppercase truncate text-xs" title={client.legalName}>{client.legalName}</p>
                  </td>
                  <td className="px-6 py-5">
                     <span className={`font-black font-mono tracking-widest uppercase text-xs ${client.gstProfile?.gstStatus === 'Closed' ? 'text-red-600' : 'text-indigo-600'}`}>{client.gstProfile?.gstin}</span>
                  </td>
                  <td className="px-6 py-5">
                     <span className={`px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                       client.gstProfile?.gstStatus === 'Closed' ? 'bg-red-50 text-red-600 border-red-100' : 
                       client.gstProfile?.gstStatus === 'Suspended' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                       'bg-emerald-50 text-emerald-600 border-emerald-100'
                     }`}>
                       {client.gstProfile?.gstStatus || 'Active'}
                     </span>
                  </td>
                  <td className="px-6 py-5">
                     <span className={`px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                       client.status === 'Active' || client.status === 'Active Filing' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 
                       client.status === 'Litigation' ? 'bg-rose-50 text-rose-600 border-rose-100 animate-pulse' :
                       'bg-slate-50 text-slate-400 border-slate-200'
                     }`}>
                       {client.status}
                     </span>
                  </td>
                  <td className="px-6 py-5 text-right relative overflow-visible">
                     <div className="flex items-center justify-end gap-2">
                        <button 
                          onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }}
                          className="h-9 w-9 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                        >
                           <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                        </button>

                        <div className="relative inline-block text-left">
                          <button 
                            onClick={() => setActiveActionsId(activeActionsId === client.id ? null : client.id)}
                            className="h-9 w-9 rounded-xl bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                          >
                             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
                          </button>

                          {activeActionsId === client.id && (
                             <div ref={actionsRef} className="absolute right-0 mt-3 w-60 bg-white border border-slate-200 rounded-[2rem] shadow-2xl z-[300] p-3 animate-in zoom-in-95 origin-top-right overflow-hidden">
                                <button onClick={() => { setLoginToolClient(client); setTempPass(client.gstProfile?.password || ''); setIsLoginBoxOpen(true); setActiveActionsId(null); }} 
                                   className="w-full flex items-center gap-4 px-4 py-3.5 hover:bg-indigo-50 rounded-2xl transition-colors text-left group">
                                   <div className="h-10 w-10 rounded-xl bg-indigo-50 flex items-center justify-center text-indigo-600 group-hover:bg-white shadow-sm"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg></div>
                                   <span className="text-[11px] font-black uppercase tracking-widest text-slate-700">Login Portal</span>
                                </button>
                                <div className="my-2 border-t border-slate-100" />
                                <button onClick={() => { setSelectedClient(client); setIsEditModalOpen(true); setActiveActionsId(null); }} 
                                   className="w-full flex items-center gap-4 px-4 py-3.5 hover:bg-slate-50 rounded-2xl transition-colors text-left group">
                                   <div className="h-10 w-10 rounded-xl bg-slate-100 flex items-center justify-center text-slate-500 group-hover:bg-white shadow-sm"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></div>
                                   <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Edit Records</span>
                                </button>
                                <button onClick={() => { if(confirm('Delete client permanently?')) api.deleteClient(client.id).then(fetch); setActiveActionsId(null); }} 
                                   className="w-full flex items-center gap-4 px-4 py-3.5 hover:bg-red-50 rounded-2xl transition-colors text-left group">
                                   <div className="h-10 w-10 rounded-xl bg-red-50 flex items-center justify-center text-red-500 group-hover:bg-white shadow-sm"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></div>
                                   <span className="text-[11px] font-black uppercase tracking-widest text-red-600">Delete Vault</span>
                                </button>
                             </div>
                          )}
                        </div>
                     </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <GSTClientFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={handleDataChange} initialData={selectedClient} />

      {/* Login Tool Box Modal */}
      {isLoginBoxOpen && loginToolClient && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/80 backdrop-blur-xl p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-lg bg-white rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 border border-slate-200">
              <div className="p-8 bg-slate-900 text-white flex items-center justify-between">
                 <div className="min-w-0">
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400 mb-2">Portal Access Utility</p>
                    <h3 className="text-xl font-black uppercase truncate">{loginToolClient.tradeName}</h3>
                 </div>
                 <button onClick={() => setIsLoginBoxOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-white/10 transition-colors"><svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>

              <div className="p-10 space-y-8">
                 <div className="space-y-4">
                    <div className="flex items-center justify-between px-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Entity GSTIN</span>
                       <button onClick={() => window.open(`https://services.gst.gov.in/services/searchtp?gstin=${loginToolClient.gstProfile?.gstin}`, '_blank')} className="text-[9px] font-black uppercase text-indigo-600 hover:underline">Verify Identity</button>
                    </div>
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                       <code className="text-lg font-black text-indigo-600 font-mono tracking-widest uppercase">{loginToolClient.gstProfile?.gstin}</code>
                       <button onClick={() => { copyToClipboard(loginToolClient.gstProfile?.gstin || ''); alert('Copied'); }} className="p-2 text-slate-300 hover:text-indigo-600 transition-colors"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg></button>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Portal User ID</span>
                       <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                          <span className="text-sm font-black text-slate-900 uppercase truncate">{loginToolClient.gstProfile?.username}</span>
                          <button onClick={() => { copyToClipboard(loginToolClient.gstProfile?.username || ''); alert('Copied'); }} className="p-1.5 text-slate-300 hover:text-indigo-600 transition-colors"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg></button>
                       </div>
                    </div>
                    <div className="space-y-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Password</span>
                       <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                          {isEditingLoginPass ? (
                             <input 
                                autoFocus
                                value={tempPass} 
                                onChange={e => setTempPass(e.target.value)} 
                                onBlur={handleUpdatePassword}
                                onKeyDown={e => e.key === 'Enter' && handleUpdatePassword()}
                                className="bg-white border border-indigo-200 rounded-lg px-2 py-1 text-xs font-black w-full outline-none focus:ring-2 focus:ring-indigo-100"
                             />
                          ) : (
                             <>
                                <span className="text-sm font-black text-indigo-600 tracking-wider truncate">{showLoginPass ? loginToolClient.gstProfile?.password : '••••••••'}</span>
                                <div className="flex gap-1.5">
                                   <button onClick={() => setShowLoginPass(!showLoginPass)} className="p-1 text-slate-300 hover:text-indigo-600">{showLoginPass ? '🙈' : '👁️'}</button>
                                   <button onClick={() => setIsEditingLoginPass(true)} className="p-1 text-slate-300 hover:text-amber-500"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
                                </div>
                             </>
                          )}
                       </div>
                    </div>
                 </div>
              </div>

              <div className="p-8 bg-slate-50 border-t border-slate-100">
                 <button 
                   onClick={() => { copyToClipboard(loginToolClient.gstProfile?.username || ''); window.open('https://services.gst.gov.in/services/login', '_blank'); }}
                   className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-slate-900 transition-all shadow-2xl active:scale-[0.98] flex items-center justify-center gap-3"
                 >
                    Launch Portal & Sync ID
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Full Detail View Modal */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[450] flex items-center justify-center bg-slate-900/70 backdrop-blur-xl p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl max-h-[95vh] bg-white rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 border border-slate-200">
            <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="min-w-0">
                 <h2 className="text-2xl font-black text-slate-900 tracking-tight leading-none uppercase truncate">{selectedClient.tradeName || selectedClient.legalName}</h2>
                 <p className="text-sm font-bold text-slate-500 mt-2 uppercase tracking-widest truncate">{selectedClient.legalName}</p>
              </div>
              <div className="flex items-center gap-3 shrink-0">
                <button onClick={() => { if(confirm('Permanently wipe record?')) api.deleteClient(selectedClient.id).then(() => { setIsDetailModalOpen(false); fetch(); }); }} className="h-11 px-6 bg-white border border-red-100 text-red-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-50 transition-all">Remove</button>
                <button onClick={() => { setIsEditModalOpen(true); setIsDetailModalOpen(false); }} className="h-11 px-10 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">Modify</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-11 w-11 flex items-center justify-center rounded-xl bg-slate-100 hover:bg-slate-200 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>
            </div>

            <div className="p-10 overflow-y-auto no-scrollbar flex-1 space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                  <section className="space-y-6 col-span-1 md:col-span-2">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Compliance Overview <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="grid grid-cols-2 gap-8">
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">GSTIN Identity</p><p className={`text-base font-black font-mono tracking-widest ${selectedClient.gstProfile?.gstStatus === 'Closed' ? 'text-red-600' : 'text-indigo-600'}`}>{selectedClient.gstProfile?.gstin}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Statutory Status</p><p className={`text-base font-black uppercase ${selectedClient.gstProfile?.gstStatus === 'Closed' ? 'text-red-600' : 'text-emerald-600'}`}>{selectedClient.gstProfile?.gstStatus || 'Active'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Registration Date</p><p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.regDate || '---'}</p></div>
                        {selectedClient.gstProfile?.gstStatus === 'Closed' && (
                           <div><p className="text-[9px] font-black uppercase text-rose-400 mb-1">Cancellation Date</p><p className="text-base font-black text-rose-600">{selectedClient.gstProfile?.cancelDate || '---'}</p></div>
                        )}
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Constitution</p><p className="text-base font-black text-slate-900 uppercase">{selectedClient.gstProfile?.constitution}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Tax Scheme</p><p className="text-base font-black text-slate-900 uppercase">{selectedClient.gstProfile?.regType} ({selectedClient.gstProfile?.filingFreq})</p></div>
                     </div>
                  </section>

                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Financial Hub <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 space-y-5">
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Primary Bank</p><p className="text-sm font-black text-slate-900 uppercase">{selectedClient.bankDetails?.bankName || '---'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">A/C Number</p><p className="text-sm font-black text-slate-900 font-mono tracking-tight">{selectedClient.bankDetails?.accountNo || '---'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">IFSC Code</p><p className="text-sm font-black text-indigo-600 font-mono tracking-widest">{selectedClient.bankDetails?.ifsc || '---'}</p></div>
                     </div>
                  </section>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Assigned Personnel <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="space-y-3">
                        {selectedClient.gstProfile?.stakeholders.map(s => (
                           <div key={s.id} className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between">
                              <div>
                                 <p className="text-sm font-black text-slate-900 uppercase">{s.name}</p>
                                 <p className="text-[9px] font-bold text-slate-400 font-mono tracking-widest uppercase mt-0.5">{s.pan}</p>
                              </div>
                              <div className="text-right">
                                 <p className="text-[10px] font-black text-slate-700">{s.mobile}</p>
                              </div>
                           </div>
                        ))}
                     </div>
                  </section>

                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Contacts & History <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="grid grid-cols-2 gap-4 mb-4">
                        <div className="bg-indigo-50/30 p-4 rounded-2xl border border-indigo-100/50">
                           <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">Firm Accountant</p>
                           <p className="text-sm font-black text-slate-900 uppercase">{selectedClient.gstProfile?.accountantName || '---'}</p>
                           <p className="text-[10px] font-bold text-slate-500 mt-1">{selectedClient.gstProfile?.accountantMobile || '---'}</p>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                           <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Entity Primary</p>
                           <p className="text-sm font-black text-slate-900">{selectedClient.mobile}</p>
                           <p className="text-[10px] font-bold text-slate-400 mt-1 lowercase truncate">{selectedClient.email}</p>
                        </div>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                        <p className="text-[9px] font-black uppercase text-slate-400 mb-2">Internal Office Notes</p>
                        <p className="text-xs font-medium text-slate-600 leading-relaxed italic">{selectedClient.remarks || 'No legacy history documented.'}</p>
                     </div>
                  </section>
               </div>
            </div>

            <footer className="p-8 border-t border-slate-100 bg-slate-50/50 flex justify-between items-center shrink-0">
               <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.4em]">Archived on {new Date(selectedClient.createdAt || Date.now()).toLocaleDateString()}</span>
               <button onClick={() => setIsDetailModalOpen(false)} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] shadow-2xl hover:bg-slate-900 transition-all">Close Review</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default GstMasterPortfolio;

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface UISettings {
  fontSize: number; // in px, default 16
  fontStyle: 'sans' | 'serif' | 'mono';
}

export interface User {
  id: string;
  username: string;
  user_id: string;
  email_id: string;
  mobile_no?: string;
  firm_name?: string | null;
  gstn?: string | null;
  status: 'online' | 'away' | 'offline';
  avatar?: string; // base64 string for DP
  uiSettings?: UISettings;
}

export type ActiveView = string;

export type ClientStatus = 'Active' | 'Litigation' | 'Inactive' | 'Active Filing';
export type GstStatus = 'Active' | 'Suspended' | 'Closed';
export type GstRegType = 'Regular' | 'Composition';
export type GstFilingFreq = 'Monthly' | 'Quarterly';
export type ConstitutionType = 'Proprietorship' | 'Partnership' | 'HUF' | 'Company' | 'Trust' | 'Society' | 'Other';
export type JurisdictionType = 'Center' | 'State';

export interface Stakeholder {
  id: string;
  name: string;
  mobile: string;
  pan: string;
  itPassword?: string;
  address?: string;
}

export interface GSTProfile {
  gstin: string;
  pan?: string;
  username: string;
  password?: string;
  gstStatus: GstStatus;
  regDate: string;
  cancelDate?: string;
  regType: GstRegType;
  filingFreq: GstFilingFreq;
  constitution: ConstitutionType;
  stakeholders: Stakeholder[];
  accountantName?: string;
  accountantMobile?: string;
  address?: string;
  jurisdictionType?: JurisdictionType;
  sector?: string;
  range?: string;
}

export type NatureOfWork = 'Salaried' | 'Business' | 'Profession' | 'House Property' | 'Capital Gain' | 'Others';

export interface ITProfile {
  pan: string;
  category: string;
