      'lit-notice-filed': { label: 'Filed Notices', desc: 'Archived notice replies awaiting orders' },
      'lit-notice-drop': { label: 'Closed Notices', desc: 'Notices dropped or relief granted' },
      'lit-notice-demand': { label: 'Confirmed Demands', desc: 'Notices converted to confirmed tax demands' },
      'lit-appeal-pending': { label: 'Pending Appeals', desc: 'Drafting and preparation for first appeals' },
      'lit-appeal-filed': { label: 'Filed Appeals', desc: 'Appeals awaiting hearing or adjudication' },
      'lit-appeal-drop': { label: 'Relief Appeals', desc: 'Appeals decided in favor of the taxpayer' },
      'lit-appeal-demand': { label: 'Sustained Appeals', desc: 'Appeals resulting in sustained demands' },
      'misc-gst-reg': { label: 'GST Registration', desc: 'New enrollment and amendment tracking' },
      'misc-food-lic': { label: 'Food License', desc: 'FSSAI registration and renewal tracking' },
      'misc-msme': { label: 'MSME Registration', desc: 'Udyam registration and certificate tracking' },
      'misc-work': { label: 'Work Log', desc: 'Miscellaneous task and staff management' },
      'messenger': { label: 'Vault Messenger', desc: 'Secure internal firm communication' },
      'reminders': { label: 'Reminders', desc: 'Consolidated compliance deadline monitor' },
      'admin-invoices': { label: 'Invoice Hub', desc: 'Professional billing and receivable tracking' },
      'admin-payments': { label: 'Collections', desc: 'Payment realization and history' },
      'admin-duedates': { label: 'Compliance Calendar', desc: 'Global due date management matrix' },
      'settings': { label: 'Vault Settings', desc: 'Firm configuration and security protocols' },
      'trash': { label: 'Vault Audit', desc: 'Permanent record and system activity log' }
    };
    return mappings[activeView] || defaultInfo;
  }, [activeView]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#fcfdfe] relative">
      <Sidebar 
        activeView={activeView} 
        onViewChange={handleViewChange} 
        isCollapsed={isSidebarCollapsed} 
        onToggle={() => setIsSidebarCollapsed(!isSidebarCollapsed)} 
      />
      <main className={`flex flex-1 flex-col overflow-hidden relative transition-all duration-500 ${isSidebarCollapsed ? 'ml-20' : 'ml-80'}`}>
        <Header 
          isConnected={isOnline} 
          currentUser={user} 
          onMenuClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} 
          activeViewLabel={headerInfo.label} 
          activeViewDescription={headerInfo.desc} 
        />
        <div className="flex-1 flex flex-col min-h-0 px-4 md:px-10 lg:px-16 pt-8 pb-12 overflow-y-auto no-scrollbar scroll-smooth">
          {isInitialLoad && activeView === 'dashboard' ? <Loader /> : (
            <Suspense fallback={<Loader />}>{renderContent()}</Suspense>
          )}
        </div>
      </main>
      <CommandPalette isOpen={isPaletteOpen} onClose={() => setIsPaletteOpen(false)} onViewChange={handleViewChange} />

      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => loadData()} />
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => loadData()} />
    </div>
  );
};

