              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                <DashboardCard title="GST Portfolio" countObj={{ total: clients.filter(c => !!c.gstProfile).length }} viewId="gst-portfolio" color="bg-indigo-600" icon={<path d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16" />} />
                <DashboardCard title="IT Portfolio" countObj={{ total: clients.filter(c => !!c.itProfile).length }} viewId="it-portfolio" color="bg-emerald-600" icon={<path d="M17 20h5v-2a3 3 0 00-5.356-1.857" />} />
              </div>
            </section>

            <section>
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-300 mb-6 flex items-center gap-4">Returns Compliance <div className="h-px flex-1 bg-slate-100" /></h2>
