                <DashboardCard title="Quarterly" viewId="compliance-quarterly" color="bg-blue-500" icon={<path d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6" />} dueDate={getDueDate('quarterly_iff', quarterlyFilter.quarter, quarterlyFilter.year)} filters={<><select value={quarterlyFilter.year} onChange={e => setQuarterlyFilter({...quarterlyFilter, year: e.target.value})} className="bg-slate-100 px-1 py-0.5 rounded text-[8px] font-black">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select><select value={quarterlyFilter.quarter} onChange={e => setQuarterlyFilter({...quarterlyFilter, quarter: e.target.value})} className="bg-slate-100 px-1 py-0.5 rounded text-[8px] font-black">{FY_QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}</select></>} countObj={getFilingCounts('quarterly', `${quarterlyFilter.year}_${quarterlyFilter.quarter}`)} />
