      ]
    }
  ];

  const handleItemClick = (item: NavItem) => {
    const hasChildren = !!item.children?.length;
    if (hasChildren) {
      // Improved: Allow folder click even when collapsed to trigger the popover/expansion more naturally
      setExpandedFolders(prev => prev.includes(item.id) ? prev.filter(f => f !== item.id) : [...prev, item.id]);
    } else {
      onViewChange(item.id as ActiveView);
    }
  };

  const renderItem = (item: NavItem, level = 0) => {
    const isExpanded = expandedFolders.includes(item.id);
    const isActive = activeView === item.id || item.children?.some(c => c.id === activeView);
    const hasChildren = !!item.children?.length;

    return (
      <div key={item.id} className="w-full group/item relative">
        <button
          onClick={() => handleItemClick(item)}
          className={`flex w-full items-center gap-4 rounded-2xl transition-all duration-300 ${
            isCollapsed ? 'justify-center py-4' : 'px-4 py-3'
          } ${
            isActive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900'
          } ${!isCollapsed && level > 0 ? 'ml-6' : ''}`}
        >
          {item.icon && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 shrink-0 transition-transform group-hover/item:scale-110 ${isActive ? 'text-white' : 'text-slate-400 group-hover/item:text-indigo-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {item.icon}
            </svg>
          )}

          {!isCollapsed && <span className="flex-1 text-left truncate font-black text-[11px] uppercase tracking-wider">{item.label}</span>}

          {!isCollapsed && hasChildren && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform ${isExpanded ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
            </svg>
          )}
        </button>

        {isCollapsed && (
          <div className="absolute left-full top-0 ml-2 pointer-events-auto opacity-0 group-hover/item:opacity-100 transition-all z-[100] translate-x-2 group-hover/item:translate-x-0">
             {!hasChildren ? (
                <div className="bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-lg shadow-xl whitespace-nowrap">
                   {item.label}
                </div>
             ) : (
                <div className="bg-white border border-slate-200 rounded-2xl shadow-2xl overflow-hidden min-w-[200px] py-2">
                   <div className="px-4 py-2 border-b border-slate-100 mb-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.label}</p>
                   </div>
                   {item.children?.map(child => (
                     <button 
                       key={child.id}
                       onClick={() => onViewChange(child.id as ActiveView)}
                       className={`w-full text-left px-4 py-2.5 text-[10px] font-black uppercase tracking-widest transition-all ${activeView === child.id ? 'text-indigo-600 bg-indigo-50' : 'text-slate-600 hover:bg-slate-50'}`}
                     >
                        {child.label}
                     </button>
                   ))}
                </div>
             )}
          </div>
        )}

        {!isCollapsed && hasChildren && isExpanded && (
          <div className="mt-1 space-y-1 border-l-2 border-slate-100 ml-6 pl-2 animate-in slide-in-from-top-2 duration-200">
            {item.children?.map(child => (
              <button
                key={child.id}
                onClick={() => onViewChange(child.id as ActiveView)}
                className={`w-full text-left px-4 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${
                  activeView === child.id ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
                }`}
              >
                {child.label}
              </button>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside 
      className={`fixed inset-y-0 left-0 z-[70] flex flex-col border-r border-slate-200 bg-white shadow-2xl transition-all duration-500 ease-in-out ${
        isCollapsed ? 'w-20' : 'w-80'
      }`}
    >
      <div className={`flex h-16 md:h-20 items-center border-b border-slate-100 shrink-0 ${isCollapsed ? 'justify-center' : 'px-6 justify-between'}`}>
         {!isCollapsed && (
           <div className="flex items-center gap-3 animate-in fade-in duration-500">
             <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-600 text-white shadow-md">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <span className="text-xl font-black text-slate-900 tracking-tight">Client<span className="text-indigo-600">ify</span></span>
           </div>
         )}
         {isCollapsed && (
           <div className="h-10 w-10 rounded-xl bg-indigo-50 flex items-center justify-center text-indigo-600 shadow-sm border border-indigo-100">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
           </div>
         )}
      </div>

      <nav className="flex-1 overflow-y-auto p-4 space-y-8 no-scrollbar scroll-smooth">
        {navigation.map((group, i) => (
          <div key={i} className="space-y-3">
            {!isCollapsed && <h5 className="px-4 text-[9px] font-black uppercase tracking-[0.3em] text-slate-400">{group.group}</h5>}
            <div className="space-y-1">{group.items.map(item => renderItem(item))}</div>
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-100">
         <button 
           onClick={onToggle}
           className="w-full flex items-center justify-center h-12 rounded-2xl bg-slate-50 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600 transition-all border border-slate-100"
         >
           <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 transition-transform duration-500 ${isCollapsed ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 19l-7-7m0 0l7-7m-7 7h16" />
           </svg>
           {!isCollapsed && <span className="text-[10px] font-black uppercase tracking-widest ml-3">Minimize Vault</span>}
         </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { 
  Client, 
  ConstitutionType, 
  GstRegType, 
  GstFilingFreq, 
  ClientStatus, 
  Stakeholder,
  GstStatus,
  BankDetails
} from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const defaultStakeholder = (): Stakeholder => ({
    id: Math.random().toString(36).substr(2, 9),
    name: '',
    mobile: '',
    pan: '',
    itPassword: '',
    address: ''
  });

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active',
    gstProfile: {
      gstin: '',
      pan: '',
      username: '',
      password: '',
      gstStatus: 'Active',
      regDate: '',
      cancelDate: '',
      regType: 'Regular',
      filingFreq: 'Monthly',
      constitution: 'Proprietorship',
      stakeholders: [defaultStakeholder()],
      accountantName: '',
      accountantMobile: '',
      address: '',
      jurisdictionType: 'State'
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setFormData({
          ...initialData,
          gstProfile: {
            ...initialData.gstProfile!,
            stakeholders: initialData.gstProfile?.stakeholders || [defaultStakeholder()]
          }
        });
      } else {
        resetForm();
      }
    }
  }, [isOpen, initialData]);

  const resetForm = () => {
    setFormData({
      legalName: '',
      tradeName: '',
      email: '',
      mobile: '',
      status: 'Active',
      gstProfile: {
        gstin: '',
        pan: '',
        username: '',
        password: '',
        gstStatus: 'Active',
        regDate: '',
        cancelDate: '',
        regType: 'Regular',
        filingFreq: 'Monthly',
        constitution: 'Proprietorship',
        stakeholders: [defaultStakeholder()],
        accountantName: '',
        accountantMobile: '',
        address: '',
        jurisdictionType: 'State'
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
  };

  // Logic to auto-fetch Legal Name based on Constitution and Stakeholder 0
  const syncLegalName = (constitution: ConstitutionType, firstStakeholderName: string) => {
    if (!firstStakeholderName) return;

    let derivedName = formData.legalName || '';
    if (constitution === 'Proprietorship') {
      derivedName = firstStakeholderName;
    } else if (constitution === 'HUF') {
      derivedName = firstStakeholderName.includes('HUF') ? firstStakeholderName : `${firstStakeholderName} HUF`;
    }

    setFormData(prev => ({ ...prev, legalName: derivedName.toUpperCase() }));
  };

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().trim().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';
    if (gstin.length >= 10) pan = gstin.substring(2, 12);

    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        gstin,
        pan,
        username: prev.gstProfile?.username || gstin,
        stakeholders: prev.gstProfile!.stakeholders.map((s, idx) => 
          idx === 0 && !s.pan ? { ...s, pan: pan } : s
        )
      }
    }));
  };

  const handleRegTypeChange = (type: GstRegType) => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        regType: type,
        // Auto-select Quarterly for Composition taxpayers
        filingFreq: type === 'Composition' ? 'Quarterly' : prev.gstProfile?.filingFreq || 'Monthly'
      }
    }));
  };

  const handleConstitutionChange = (val: ConstitutionType) => {
    const firstStakeholder = formData.gstProfile?.stakeholders[0]?.name || '';
    setFormData(prev => ({
      ...prev,
      gstProfile: { ...prev.gstProfile!, constitution: val }
    }));
    syncLegalName(val, firstStakeholder);
  };

  const updateStakeholder = (id: string, field: keyof Stakeholder, val: string) => {
    setFormData(prev => {
      const updatedStakeholders = prev.gstProfile!.stakeholders.map(s => 
        s.id === id ? { ...s, [field]: val } : s
      );

      // If updating first member name and constitution is Proprietorship/HUF, sync Legal Name
      if (field === 'name' && updatedStakeholders[0].id === id) {
        setTimeout(() => syncLegalName(prev.gstProfile!.constitution, val.toUpperCase()), 0);
      }

      return {
        ...prev,
        gstProfile: {
          ...prev.gstProfile!,
          stakeholders: updatedStakeholders
        }
      };
    });
  };

  const addStakeholder = () => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        stakeholders: [...prev.gstProfile!.stakeholders, defaultStakeholder()]
      }
    }));
  };

  const removeStakeholder = (id: string) => {
    setFormData(prev => {
      if (prev.gstProfile!.stakeholders.length <= 1) return prev;
      return {
        ...prev,
        gstProfile: {
          ...prev.gstProfile!,
          stakeholders: prev.gstProfile!.stakeholders.filter(s => s.id !== id)
        }
      };
    });
  };

  const handleSave = async () => {
    setError(null);
    if (!formData.tradeName) return setError("Trade Name is mandatory.");
    if (!formData.gstProfile?.gstin) return setError("GSTIN identifier required.");

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Failed to archive profile.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  const isProprietorship = formData.gstProfile?.constitution === 'Proprietorship';

  return (
    <div className="fixed inset-0 z-[400] flex items-center justify-center bg-slate-900/70 backdrop-blur-xl p-4 overflow-hidden animate-in fade-in duration-300">
      <div className="w-full max-w-5xl bg-white rounded-[3rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden border border-slate-200">

        <header className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
             <div className="h-14 w-14 rounded-2xl bg-indigo-600 flex items-center justify-center text-white shadow-xl shadow-indigo-100">
