    let total = 0;
    let filed = 0;

    if (type === 'monthly') {
      const applicable = clients.filter(c => c.gstProfile?.regType === 'Regular' && c.gstProfile?.filingFreq === 'Monthly');
      total = applicable.length;
      filed = applicable.filter(c => periodData[c.id]?.r1 && periodData[c.id]?.r3b).length;
