              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div onClick={() => handleViewChange('gst-portfolio')} className="group bg-white rounded-[2rem] border border-slate-200 p-8 shadow-sm hover:border-indigo-400 hover:shadow-2xl transition-all cursor-pointer relative overflow-hidden">
                   <div className="absolute top-0 right-0 h-40 w-40 bg-indigo-600/5 -mr-10 -mt-10 rounded-full blur-3xl group-hover:bg-indigo-600/10 transition-colors" />
                   <div className="flex items-start justify-between relative z-10">
                      <div>
                        <div className="h-14 w-14 rounded-2xl bg-indigo-600 flex items-center justify-center text-white shadow-lg mb-6 group-hover:scale-110 transition-transform">
                           <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16" /></svg>
                        </div>
                        <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">GST Portfolio</h3>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-2">Active Regular & Comp. Entities</p>
                      </div>
                      <div className="text-right">
                        <p className="text-4xl font-black text-slate-900">{clients.filter(c => !!c.gstProfile).length}</p>
                        <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] mt-1">Total Vault</p>
                      </div>
                   </div>
                </div>
                <div onClick={() => handleViewChange('it-portfolio')} className="group bg-white rounded-[2rem] border border-slate-200 p-8 shadow-sm hover:border-emerald-400 hover:shadow-2xl transition-all cursor-pointer relative overflow-hidden">
                   <div className="absolute top-0 right-0 h-40 w-40 bg-emerald-600/5 -mr-10 -mt-10 rounded-full blur-3xl group-hover:bg-emerald-600/10 transition-colors" />
                   <div className="flex items-start justify-between relative z-10">
                      <div>
                        <div className="h-14 w-14 rounded-2xl bg-emerald-600 flex items-center justify-center text-white shadow-lg mb-6 group-hover:scale-110 transition-transform">
                           <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857" /></svg>
                        </div>
                        <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">IT Portfolio</h3>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-2">Personal & Corporate Direct Tax</p>
                      </div>
                      <div className="text-right">
                        <p className="text-4xl font-black text-slate-900">{clients.filter(c => !!c.itProfile).length}</p>
                        <p className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.2em] mt-1">Total Vault</p>
                      </div>
                   </div>
                </div>
              </div>
            </section>
            <section>
              <SectionHeader title="Compliance Matrix" subtitle="Statutory Filing Lifecycle" />
              <div className="space-y-10">
                 <div>
                    <SubSectionTitle title="Filing Cycles" />
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                       <CompactCard label="Monthly" count={getFilingCounts('monthly', `${monthlyFilter.year}_${monthlyFilter.month}`).total} viewId="compliance-monthly" color="bg-indigo-600" icon={<path d="M8 7V3m8 4V3m-9 8h10" />} />
                       <CompactCard label="Quarterly" count={getFilingCounts('quarterly', `${quarterlyFilter.year}_${quarterlyFilter.quarter}`).total} viewId="compliance-quarterly" color="bg-blue-600" icon={<path d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6z" />} />
                       <CompactCard label="Composition" count={getFilingCounts('composition', `${compositionFilter.year}_${compositionFilter.quarter}`).total} viewId="compliance-composition" color="bg-amber-600" icon={<path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5" />} />
                    </div>
                 </div>
                 <div>
                    <SubSectionTitle title="Annual Returns" />
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                       <CompactCard label="GSTR-04 Annual" count={clients.filter(c => c.gstProfile?.regType === 'Composition').length} viewId="compliance-gstr4" color="bg-indigo-400" icon={<path d="M12 8v4l3 3" />} />
                       <CompactCard label="GSTR-9/9C Audit" count={clients.filter(c => c.gstProfile?.regType === 'Regular').length} viewId="compliance-gstr9" color="bg-indigo-800" icon={<path d="M9 17v-2m3 2v-4m3 4v-6m2 10H7" />} />
                    </div>
                 </div>
                 <div>
                    <SubSectionTitle title="IT & Audit" />
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                       <CompactCard label="ITR Returns" count={getFilingCounts('itr', itrFilter.ay).total} viewId="compliance-itr" color="bg-emerald-600" icon={<path d="M17 9V7a2 2 0 00-2-2H5" />} />
                       <CompactCard label="Audit & B/S" count={clients.filter(c => c.itProfile?.advisoryWork?.taxAudit).length} viewId="compliance-taxaudit" color="bg-emerald-400" icon={<path d="M9 12h6m-6 4h6" />} />
                    </div>
                 </div>
              </div>
            </section>
            <section>
              <SectionHeader title="Litigation Suite" subtitle="Legal Defense Command" />
              <div className="grid grid-cols-1 gap-12">
                 <LitigationBlock forum="Notice" label="GST Notices" icon={<path d="M12 9v2m0 4h.01" />} />
                 <LitigationBlock forum="Appeal" label="GST Appeals" icon={<path d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2" />} />
                 <LitigationBlock forum="Tribunal" label="GSTAT (Tribunal)" icon={<path d="M3 6l3 1m0 0l-3 9" />} />
                 <LitigationBlock forum="HighCourt" label="High Court Matters" icon={<path d="M8 14v20c0 4.418 7.163 8 16 8" />} />
              </div>
            </section>
          </div>
        );
      case 'gst-portfolio': return <GSTPortfolio />;
      case 'it-portfolio': return <ITPortfolio />;
      case 'compliance-monthly': return <MonthlyFiling onViewChange={handleViewChange} />;
      case 'compliance-quarterly': return <QuarterlyFiling />;
      case 'compliance-composition': return <CompositionFiling />;
      case 'compliance-gstr4': return <GSTR4 />;
      case 'compliance-gstr9': return <GSTR9_9C />;
      case 'compliance-itr': return <ITRReturn />;
      case 'compliance-taxaudit': return <TAXAudit />;
      case 'gst-view-detail': return <GSTviewicon client={viewExtra} onBack={() => handleViewChange('gst-portfolio')} />;
      case 'it-view-detail': return <ITviewicon client={viewExtra} onBack={() => handleViewChange('it-portfolio')} />;
      case 'admin-invoices': return <Invoices onViewChange={handleViewChange} />;
      case 'admin-add-invoice': return <AddInvoice onBack={() => handleViewChange('admin-invoices')} editingInvoice={viewExtra} />;
      case 'admin-payments': return <PaymentReceived onViewChange={handleViewChange} />;
      case 'admin-duedates': return <DueDateSetting />;
      case 'settings': return <Setting />;
      case 'trash': return <Trash />;
      case 'messenger': return <Messenger />;
      case 'reminders': return <Reminders />;
      case 'misc-gst-reg': return <GSTRegistration />;
      case 'misc-food-lic': return <FoodLicenses />;
      case 'misc-msme': return <MSMERegistration />;
      case 'misc-work': return <Miscellaneouswork />;
      default: return <div className="p-20 text-center text-slate-300 font-black uppercase tracking-widest text-sm">Syncing module...</div>;
    }
  };

  const headerInfo = useMemo(() => {
    const mappings: Record<string, { label: string; desc: string }> = {
      'dashboard': { label: 'Dashboard', desc: 'Practice Intelligence Operating System' },
      'gst-portfolio': { label: 'GST Portfolio', desc: 'Master GST Client Vault' },
      'it-portfolio': { label: 'IT Portfolio', desc: 'Master Income Tax Client Vault' },
      'gst-view-detail': { label: 'Client Insight', desc: 'Detailed Statutory Review' },
      'it-view-detail': { label: 'Tax Profile', desc: 'Direct Tax Vault Snapshot' },
      'compliance-monthly': { label: 'Monthly Returns', desc: 'GSTR-1 and GSTR-3B Lifecycle' }
    };
    return mappings[activeView] || { label: 'Vault Access', desc: 'Authorized Practice Management' };
  }, [activeView]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#fcfdfe] relative">
      {isSidebarOpen && (
        <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 z-[90] bg-slate-900/40 backdrop-blur-md transition-opacity duration-500 animate-in fade-in" />
      )}
      <Sidebar activeView={activeView} onViewChange={handleViewChange} isOpen={isSidebarOpen} onToggle={() => setIsSidebarOpen(!isSidebarOpen)} />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header isConnected={isOnline} currentUser={user} onMenuClick={() => setIsSidebarOpen(true)} activeViewLabel={headerInfo.label} activeViewDescription={headerInfo.desc} onViewChange={handleViewChange} />
        <div className="flex-1 flex flex-col min-h-0 px-4 md:px-10 lg:px-16 pt-8 pb-12 overflow-y-auto no-scrollbar scroll-smooth">
          {isInitialLoad && activeView === 'dashboard' ? <Loader /> : (
            <Suspense fallback={<Loader />}>{renderContent()}</Suspense>
          )}
        </div>
      </main>
      <CommandPalette isOpen={isPaletteOpen} onClose={() => setIsPaletteOpen(false)} onViewChange={handleViewChange} />
      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => loadData()} />
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => loadData()} />
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { api } from '../../../services/api.ts';
import Loader from '../../../components/Loader';
import { useMonthlyFilingLogic, MONTHS, YEARS, getDefaultPeriod } from './filinglogic/MonthlyFilingLogic';

interface MonthlyFilingProps {
  onViewChange?: (view: string, extra?: any) => void;
}

const MonthlyFiling: React.FC<MonthlyFilingProps> = ({ onViewChange }) => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedMonth, setSelectedMonth] = useState(defaultPeriod.month);

  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3Filter, setR3Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [isR1FilterOpen, setIsR1FilterOpen] = useState(false);
  const [isR3FilterOpen, setIsR3FilterOpen] = useState(false);

  const [activeActionsId, setActiveActionsId] = useState<string | null>(null);
  const [editingPassId, setEditingPassId] = useState<string | null>(null);
  const [tempPass, setTempPass] = useState('');

  const { getStatus, toggleStatus, updateDueDate, getDueDate } = useMonthlyFilingLogic(selectedYear, selectedMonth);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setClients(data.filter(c => 
        (c.status === 'Active Filing' || c.status === 'Litigation') && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Monthly'
      ));
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const filteredClients = useMemo(() => {
    const s = search.toLowerCase();
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );

    if (r1Filter !== 'All') list = list.filter(c => r1Filter === 'Filed' ? getStatus(c.id).r1 : !getStatus(c.id).r1);
    if (r3Filter !== 'All') list = list.filter(c => r3Filter === 'Filed' ? getStatus(c.id).r3b : !getStatus(c.id).r3b);

    return list;
  }, [clients, search, r1Filter, r3Filter, getStatus]);

  const copyAndOpen = (id: string, username: string) => {
    navigator.clipboard.writeText(username);
    window.open(`https://services.gst.gov.in/services/login`, '_blank');
  };

  const handleUpdatePass = async (client: Client) => {
    if (!tempPass.trim()) return;
    const updated = { ...client, gstProfile: { ...client.gstProfile!, password: tempPass } };
    await api.saveClient(updated);
    setClients(prev => prev.map(c => c.id === client.id ? (updated as Client) : c));
    setEditingPassId(null);
  };

  const shareViaWhatsApp = (text: string) => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search entity in monthly matrix..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-4 focus:ring-indigo-50 outline-none" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <div className="flex gap-2 shrink-0">
           <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 rounded-xl px-4 py-3 text-[11px] font-black uppercase text-slate-600 cursor-pointer outline-none">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
           <select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 rounded-xl px-4 py-3 text-[11px] font-black uppercase text-slate-600 cursor-pointer outline-none">{MONTHS.map(m => <option key={m} value={m}>{m}</option>)}</select>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1500px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Trade Name</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Legal Name</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center w-[120px] relative">
                  <div className="flex items-center justify-center gap-1">GSTR-1 <button onClick={() => setIsR1FilterOpen(!isR1FilterOpen)} className="p-1 hover:bg-slate-200 rounded"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button></div>
                  {isR1FilterOpen && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-[400] p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR1Filter(f as any); setIsR1FilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${r1Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}
                    </div>
                  )}
                </th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center w-[120px] relative">
                  <div className="flex items-center justify-center gap-1">GSTR-3B <button onClick={() => setIsR3FilterOpen(!isR3FilterOpen)} className="p-1 hover:bg-slate-200 rounded"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button></div>
                  {isR3FilterOpen && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-[400] p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR3Filter(f as any); setIsR3FilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${r3Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}
                    </div>
                  )}
                </th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[140px]">User ID</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Password</th>
                <th className="px-4 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right w-[110px]">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((c, idx) => {
                const st = getStatus(c.id);
                return (
                  <tr key={c.id} className="hover:bg-slate-50/50 transition-all group border-b border-slate-100 last:border-0">
                    <td className="px-4 py-2 font-black text-slate-300 text-[11px]">{idx + 1}</td>
                    <td className="px-4 py-2"><p className="font-black text-slate-900 uppercase truncate text-[12px]" title={c.tradeName}>{c.tradeName}</p></td>
                    <td className="px-4 py-2"><p className="font-bold text-slate-500 uppercase truncate text-[11px]" title={c.legalName}>{c.legalName}</p></td>
                    <td className="px-4 py-2">
                       <div className="flex items-center gap-1.5 group/gst">
                          <span className="font-black text-indigo-600 font-mono text-[11px]">{c.gstProfile?.gstin}</span>
                          <button onClick={() => { navigator.clipboard.writeText(c.gstProfile?.gstin || ''); window.open(`https://services.gst.gov.in/services/searchtp?gstin=${c.gstProfile?.gstin}`, '_blank'); }} 
                            className="p-1 text-slate-300 hover:text-indigo-600 transition-opacity opacity-0 group-hover/gst:opacity-100"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></button>
                       </div>
                    </td>
                    <td className="px-4 py-2 text-center">
                      <button onClick={() => toggleStatus(c.id, 'r1')} className={`px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${st.r1 ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
                        {st.r1 ? 'Filed' : 'Pending'}
                      </button>
                    </td>
                    <td className="px-4 py-2 text-center">
                      <button onClick={() => toggleStatus(c.id, 'r3b')} className={`px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${st.r3b ? 'bg-emerald-600 text-white border-emerald-700' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
                        {st.r3b ? 'Filed' : 'Pending'}
                      </button>
                    </td>
                    <td className="px-4 py-2"><p className="font-black text-slate-700 text-[11px] truncate">{c.gstProfile?.username}</p></td>
                    <td className="px-4 py-2">
                       <div className="flex items-center justify-between group/pass max-w-[140px]">
                          {editingPassId === c.id ? (
                            <input autoFocus value={tempPass} onChange={e => setTempPass(e.target.value)} onBlur={() => handleUpdatePass(c)} onKeyDown={e => e.key === 'Enter' && handleUpdatePass(c)} className="bg-white border border-indigo-200 rounded px-2 py-0.5 text-xs font-black w-full" />
                          ) : (
